// Deterministic 16 kHz mono fixture: 300 ms alternating speech, then 1000 ms silence.
// Encoded with ffmpeg 4.4.2 (libopus/libFLAC); hashes are checked in.
export const RAW_PCM_SHA256 = '095b97214735ad0450919e8105def5ad53f72df7586bca5a98b9123ab390d7c6';
export const OGG_OPUS_SHA256 = '89aa1b54a35f8c16aa1f7e40248a0fb658b69098fad1caab25c6f300c41cff52';
export const FLAC_SHA256 = '9fbcd16ce81234f8998f21758410f4527a45ad71f94421e63fa6fc82223936ef';

export function fixturePcm() {
  const samples = 16000 * 1300 / 1000;
  const pcm = Buffer.alloc(samples * 2);
  for (let i = 0; i < samples; i += 1) {
    const value = i < 16000 * 300 / 1000
      ? ((i % 4 === 0 || i % 4 === 1) ? 7000 : -7000)
      : 0;
    pcm.writeInt16LE(value, i * 2);
  }
  return pcm;
}

export const OGG_OPUS = Buffer.from('', 'base64');
export const FLAC = Buffer.from('', 'base64');

